// sql-injection-reviewed-file: disposable-cluster TEST HARNESS (database layer), never request-path code. Every DDL interpolation is an identifier generated by this harness (`fbc_<tag>_<run>`) passed through ident(), which accepts only ^[a-z_][a-z0-9_]{0,62}$ and double-quotes it; passwords go only as $n bind parameters or through format('%L') inside a DO block reading a transaction-local setting. Reviewed 2026-11-19 (provider-neutral db-setup).
/**
 * Owner decision 2026-11-19 (provider-neutral db-setup): the real-database proof of the capability-based behaviour of the
 * bootstrap child. Run by run-fallback-check.sh on a docker host (InstaBox), never against a real provider:
 *
 *   FBC_PLAIN_SU_URL   the superuser of a plain PostgreSQL 16 with TLS (server certificate for 127.0.0.1 from FBC's CA)
 *   FBC_SIM_SU_URL     the superuser of a PostgreSQL 16 that loads refuse_prehashed.c (refuses pre-hashed passwords at
 *                      COMMIT, XX000) and logs EVERY statement with its parameters (log_statement=all,
 *                      log_min_duration_statement=0)
 *   FBC_BOUNCER1_HOSTPORT / FBC_BOUNCER2_HOSTPORT   PgBouncer (transaction pooling) in front of the plain cluster: 1 with
 *                      its defaults (refuses the startup option db-setup sends), 2 with ignore_startup_parameters=options
 *   PG_SSL_CA_CERT_PATH  the CA of both clusters (handed to the child)
 *   FBC_SIM_CONTAINER / FBC_PLAIN_CONTAINER  docker container names: their logs are searched for every secret
 *
 * Scenarios (each from a clean cluster state; crewflow_owner is cluster-wide):
 *   P1  plain PG16, verify-full, a non-superuser CREATEROLE admin: the pre-hashed path (no fallback line), crewflow_owner
 *       created, its password stored as SCRAM, the login works.
 *   P2  plain PG16, the cluster superuser as the admin over verify-full (what the bundled db's mode a does): the same.
 *   S1  the refusing server, verify-full, an admin granted SET on log_statement / log_parameter_max_length: the verifier is
 *       refused at COMMIT (XX000), ONE plain-text retry, the fixed log line, crewflow_owner created and the login works, and
 *       the password appears in NO output and NO server log line although every statement is logged.
 *   S2  the refusing server, an admin WITHOUT those grants: refused (64) with the log-risk message; nothing created; the
 *       password never reached the server (not in its log).
 *   S3  the refusing server over TLS that does not verify (PG_SSL_ALLOW_SELF_SIGNED=true): refused (64) with the
 *       verified-TLS message, the refusal named as SQLSTATE XX000 at COMMIT (never "another start"); nothing created.
 *   B1  PG_ADMIN_URL through PgBouncer 1: refused (64), "refused the session settings" + PG_ADMIN_DIRECT_URL.
 *   B2  PG_ADMIN_URL through PgBouncer 2: refused (64), "not session-stable" + PG_ADMIN_DIRECT_URL; nothing created.
 *   B3  PG_ADMIN_URL through PgBouncer 2 + PG_ADMIN_DIRECT_URL (the cluster, verify-full): created (0).
 * Output: scenario ids, PASS / FAIL, never a value.
 */
import { execFileSync, spawn } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

import { Client } from 'pg';

import { OWNER_BOOTSTRAP_MESSAGES, OWNER_BOOTSTRAP_RESULT_PREFIX, OwnerBootstrapResult } from '../owner-bootstrap';

const REPO_ROOT = resolve(__dirname, '..', '..', '..', '..', '..', '..', '..', '..');
const TSCONFIG_APP = join(REPO_ROOT, 'packages', 'rab-server', 'tsconfig.app.json');
const ENTRY = join(__dirname, '..', 'bootstrap-owner-login.ts');
const RUN = `${Date.now().toString(36)}${randomBytes(2).toString('hex')}`;
const SECRETS = new Set<string>();
const remember = (v: string): string => {
  SECRETS.add(v);
  return v;
};
const log = (m: string) => process.stdout.write(`[fallback-check] ${m}\n`);

class Failed extends Error {}
function expect(cond: unknown, what: string): void {
  if (!cond) throw new Failed(what);
}

function need(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`${name} is required`);
  return v;
}

const CA_PATH = need('PG_SSL_CA_CERT_PATH');
const CA = readFileSync(CA_PATH, 'utf8');
const PLAIN = new URL(need('FBC_PLAIN_SU_URL'));
const SIM = new URL(need('FBC_SIM_SU_URL'));
for (const u of [PLAIN, SIM]) {
  if (u.hostname !== '127.0.0.1') throw new Error('loopback disposable clusters only');
  remember(decodeURIComponent(u.password));
}

function ident(name: string): string {
  if (!/^[a-z_][a-z0-9_]{0,62}$/.test(name)) throw new Error('not a plain identifier');
  return `"${name}"`;
}

function urlFor(base: URL, user: string, password: string, db: string, query = 'sslmode=verify-full', hostport?: string): string {
  const u = new URL(base.toString());
  if (hostport) u.host = hostport;
  u.username = user;
  u.password = encodeURIComponent(password);
  u.pathname = `/${db}`;
  u.search = query;
  return remember(u.toString());
}

async function sql(base: URL, db: string, text: string, values: unknown[] = []): Promise<Record<string, unknown>[]> {
  const c = new Client({
    host: base.hostname,
    port: Number(base.port),
    user: decodeURIComponent(base.username),
    password: decodeURIComponent(base.password),
    database: db,
    ssl: { ca: CA, rejectUnauthorized: true },
  });
  await c.connect();
  try {
    return (await c.query(text, values)).rows as Record<string, unknown>[];
  } finally {
    await c.end();
  }
}

async function canLogin(base: URL, user: string, password: string, db: string): Promise<boolean> {
  const c = new Client({ host: base.hostname, port: Number(base.port), user, password, database: db, ssl: { ca: CA, rejectUnauthorized: true } });
  c.on('error', () => undefined);
  try {
    await c.connect();
    await c.query('SELECT 1');
    return true;
  } catch {
    return false;
  } finally {
    await c.end().catch(() => undefined);
  }
}

const strong = (): string => remember(randomBytes(24).toString('hex'));

interface Fixture {
  db: string;
  admin: string;
  adminPassword: string;
  ownerPassword: string;
}

async function reset(base: URL): Promise<void> {
  const dbs = await sql(base, 'postgres', `SELECT datname FROM pg_catalog.pg_database WHERE datname LIKE 'fbc\\_%'`);
  for (const r of dbs) await sql(base, 'postgres', `DROP DATABASE IF EXISTS ${ident(String(r.datname))} WITH (FORCE)`);
  for (const role of ['crewflow_worker', 'crewflow_app', 'crewflow', 'rab_app', 'rab_owner', 'rab_secure_owner', 'crewflow_owner']) {
    await sql(base, 'postgres', `DROP ROLE IF EXISTS ${ident(role)}`);
  }
  const roles = await sql(base, 'postgres', `SELECT rolname FROM pg_catalog.pg_roles WHERE rolname LIKE 'fbc\\_%'`);
  for (const r of roles) await sql(base, 'postgres', `DROP ROLE IF EXISTS ${ident(String(r.rolname))}`);
}

/** A database owned by a NON-superuser CREATEROLE admin (the shape of a managed provider's admin login). */
async function fixture(base: URL, tag: string, grantLogSettings: boolean): Promise<Fixture> {
  await reset(base);
  const db = `fbc_${tag}_${RUN}`;
  const admin = `fbc_admin_${tag}_${RUN}`;
  const adminPassword = strong();
  // The admin's password goes through a transaction-local setting and %L, never statement text (the sim logs everything).
  await sql(base, 'postgres', `CREATE ROLE ${ident(admin)} LOGIN CREATEROLE`);
  const c = new Client({
    host: base.hostname,
    port: Number(base.port),
    user: decodeURIComponent(base.username),
    password: decodeURIComponent(base.password),
    database: 'postgres',
    ssl: { ca: CA, rejectUnauthorized: true },
  });
  await c.connect();
  try {
    await c.query(`SET log_statement = 'none'`);
    await c.query(`SET log_min_duration_statement = -1`);
    await c.query(`SET log_parameter_max_length = 0`);
    await c.query('BEGIN');
    await c.query(`SELECT pg_catalog.set_config('fbc.pw', $1, true)`, [adminPassword]);
    // A plain-text admin password (the refusing server accepts only plain text); the superuser session logs nothing.
    await c.query(`DO $$ BEGIN EXECUTE pg_catalog.format('ALTER ROLE %I PASSWORD %L', '${admin}', pg_catalog.current_setting('fbc.pw')); END $$`);
    await c.query('COMMIT');
  } finally {
    await c.end();
  }
  await sql(base, 'postgres', `CREATE DATABASE ${ident(db)} OWNER ${ident(admin)}`);
  if (grantLogSettings) {
    await sql(base, 'postgres', `GRANT SET ON PARAMETER log_statement, log_min_duration_statement, log_parameter_max_length TO ${ident(admin)}`);
  }
  return { db, admin, adminPassword, ownerPassword: strong() };
}

interface ChildRun {
  code: number | null;
  out: string;
  result: OwnerBootstrapResult | null;
}

function runChild(env: Record<string, string>): Promise<ChildRun> {
  const base: Record<string, string> = {};
  for (const k of ['PATH', 'HOME', 'TMPDIR']) if (process.env[k]) base[k] = process.env[k]!;
  const argv = [require.resolve('ts-node/dist/bin.js'), '--transpile-only', '-P', TSCONFIG_APP, ENTRY];
  return new Promise((done) => {
    const child = spawn(process.execPath, argv, { env: { ...base, NODE_ENV: 'test', ...env }, stdio: ['ignore', 'pipe', 'pipe'], cwd: REPO_ROOT });
    let out = '';
    child.stdout.on('data', (d) => (out += String(d)));
    child.stderr.on('data', (d) => (out += String(d)));
    child.on('close', (code) => {
      const line = out.split('\n').find((l) => l.startsWith(`${OWNER_BOOTSTRAP_RESULT_PREFIX} `));
      let result: OwnerBootstrapResult | null = null;
      try {
        result = line ? (JSON.parse(line.slice(OWNER_BOOTSTRAP_RESULT_PREFIX.length + 1)) as OwnerBootstrapResult) : null;
      } catch {
        result = null;
      }
      done({ code, out, result });
    });
  });
}

function assertClean(run: ChildRun, extra: string[] = []): void {
  for (const s of [...SECRETS, ...extra]) if (s && run.out.includes(s)) throw new Failed('a secret appeared in the child output (not shown)');
  if (/postgres(ql)?:\/\/[^\s)]*@/i.test(run.out)) throw new Failed('a URL shape appeared in the child output');
  if (run.out.includes('SCRAM-SHA-256$')) throw new Failed('a verifier appeared in the child output');
}

/** Counts lines of a container's log (stdout and stderr) holding a secret; never prints them. */
function logHits(container: string | undefined, secrets: string[]): number {
  if (!container || !/^[a-z0-9_.-]+$/.test(container)) throw new Failed('no container to read the server log from');
  const all = execFileSync('sh', ['-c', `docker logs ${container} 2>&1`], { encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 });
  if (all.length === 0) throw new Failed('the server log is empty (cannot prove anything)');
  return all.split('\n').filter((l) => secrets.some((s) => s && l.includes(s))).length;
}

async function ownerState(base: URL): Promise<{ exists: boolean; scram: boolean }> {
  const rows = await sql(base, 'postgres', `SELECT rolpassword FROM pg_catalog.pg_authid WHERE rolname = 'crewflow_owner'`);
  if (!rows[0]) return { exists: false, scram: false };
  return { exists: true, scram: String(rows[0].rolpassword ?? '').startsWith('SCRAM-SHA-256$') };
}

const fallbackLine = OWNER_BOOTSTRAP_MESSAGES.verifierRefusedFallback('commit', 'XX000');

async function created(base: URL, f: Fixture, run: ChildRun, what: string): Promise<void> {
  expect(run.code === 0 && run.result?.outcome === 'created', `${what}: exit ${run.code}, outcome ${run.result?.outcome ?? 'none'} (${run.result?.code ?? ''})`);
  const st = await ownerState(base);
  expect(st.exists && st.scram, `${what}: crewflow_owner missing or its password not stored as SCRAM`);
  expect(await canLogin(base, 'crewflow_owner', f.ownerPassword, f.db), `${what}: crewflow_owner cannot log in with its password`);
}

const scenarios: Array<[string, () => Promise<void>]> = [
  [
    'P1 plain PG16, verify-full, non-superuser admin: pre-hashed path, no fallback',
    async () => {
      const f = await fixture(PLAIN, 'p1', false);
      const run = await runChild({
        PG_ADMIN_URL: urlFor(PLAIN, f.admin, f.adminPassword, f.db),
        PG_DATABASE_URL: urlFor(PLAIN, 'crewflow_owner', f.ownerPassword, f.db),
        PG_SSL_CA_CERT_PATH: CA_PATH,
      });
      await created(PLAIN, f, run, 'P1');
      expect(!run.out.includes('pre-hashed'), 'P1: a fallback line on a server that accepts the verifier');
      assertClean(run);
    },
  ],
  [
    'P2 plain PG16, the cluster superuser as admin over verify-full (the bundled db shape): pre-hashed path',
    async () => {
      const f = await fixture(PLAIN, 'p2', false);
      const run = await runChild({
        PG_ADMIN_URL: urlFor(PLAIN, decodeURIComponent(PLAIN.username), decodeURIComponent(PLAIN.password), f.db),
        PG_DATABASE_URL: urlFor(PLAIN, 'crewflow_owner', f.ownerPassword, f.db),
        PG_SSL_CA_CERT_PATH: CA_PATH,
      });
      await created(PLAIN, f, run, 'P2');
      expect(!run.out.includes('pre-hashed'), 'P2: a fallback line on a server that accepts the verifier');
      assertClean(run);
    },
  ],
  [
    'S1 refusing server, verify-full, admin may quiet its logs: one plain-text retry, logged by reason, no secret in any log',
    async () => {
      const f = await fixture(SIM, 's1', true);
      const run = await runChild({
        PG_ADMIN_URL: urlFor(SIM, f.admin, f.adminPassword, f.db),
        PG_DATABASE_URL: urlFor(SIM, 'crewflow_owner', f.ownerPassword, f.db),
        PG_SSL_CA_CERT_PATH: CA_PATH,
      });
      await created(SIM, f, run, 'S1');
      expect(run.out.includes(fallbackLine), 'S1: the fallback line (SQLSTATE XX000 at COMMIT) is missing');
      expect(run.out.includes(OWNER_BOOTSTRAP_MESSAGES.plaintextUsed), 'S1: the "used a plain-text password over verified TLS" line is missing');
      expect(!/another start/.test(run.out), 'S1: the refusal was reported as a race');
      assertClean(run);
      expect(logHits(process.env.FBC_SIM_CONTAINER, [f.ownerPassword]) === 0, 'S1: the crewflow_owner password appears in the server log');
    },
  ],
  [
    'S2 refusing server, admin cannot quiet the logs (log_statement=all): refused 64, password never sent',
    async () => {
      const f = await fixture(SIM, 's2', false);
      const run = await runChild({
        PG_ADMIN_URL: urlFor(SIM, f.admin, f.adminPassword, f.db),
        PG_DATABASE_URL: urlFor(SIM, 'crewflow_owner', f.ownerPassword, f.db),
        PG_SSL_CA_CERT_PATH: CA_PATH,
      });
      expect(run.code === 64 && run.result?.outcome === 'refused', `S2: exit ${run.code}, outcome ${run.result?.outcome ?? 'none'}`);
      expect(run.out.includes(OWNER_BOOTSTRAP_MESSAGES.plaintextLogRisk), 'S2: the log-risk refusal is missing');
      expect(!(await ownerState(SIM)).exists, 'S2: crewflow_owner was created');
      assertClean(run);
      expect(logHits(process.env.FBC_SIM_CONTAINER, [f.ownerPassword]) === 0, 'S2: the crewflow_owner password appears in the server log');
    },
  ],
  [
    'S3 refusing server over TLS that does not verify: refused 64 (XX000 at COMMIT named, never a race), nothing created',
    async () => {
      const f = await fixture(SIM, 's3', true);
      const run = await runChild({
        PG_ADMIN_URL: urlFor(SIM, f.admin, f.adminPassword, f.db, 'sslmode=require'),
        PG_DATABASE_URL: urlFor(SIM, 'crewflow_owner', f.ownerPassword, f.db, 'sslmode=require'),
        PG_SSL_ALLOW_SELF_SIGNED: 'true',
      });
      expect(run.code === 64 && run.result?.outcome === 'refused', `S3: exit ${run.code}, outcome ${run.result?.outcome ?? 'none'}`);
      expect(run.out.includes(OWNER_BOOTSTRAP_MESSAGES.fallbackNeedsVerifiedTls('commit', 'XX000')), 'S3: the verified-TLS refusal is missing');
      expect(!/another start/.test(run.out), 'S3: the refusal was reported as a race');
      expect(!(await ownerState(SIM)).exists, 'S3: crewflow_owner was created');
      assertClean(run);
      expect(logHits(process.env.FBC_SIM_CONTAINER, [f.ownerPassword]) === 0, 'S3: the crewflow_owner password appears in the server log');
    },
  ],
  [
    'B1 PG_ADMIN_URL through PgBouncer (defaults): refused 64, session settings refused, PG_ADMIN_DIRECT_URL named',
    async () => {
      const f = await fixture(PLAIN, 'b1', false);
      const hp = need('FBC_BOUNCER1_HOSTPORT');
      const run = await runChild({
        PG_ADMIN_URL: urlFor(PLAIN, f.admin, f.adminPassword, f.db, 'sslmode=disable', hp),
        PG_DATABASE_URL: urlFor(PLAIN, 'crewflow_owner', f.ownerPassword, f.db, 'sslmode=disable', hp),
      });
      expect(run.code === 64, `B1: exit ${run.code} (${run.result?.code ?? ''})`);
      expect(run.out.includes('refused the session settings') && run.out.includes('PG_ADMIN_DIRECT_URL'), 'B1: the pooler refusal (session settings) is missing');
      expect(!(await ownerState(PLAIN)).exists, 'B1: crewflow_owner was created');
      assertClean(run);
    },
  ],
  [
    'B2 PG_ADMIN_URL through PgBouncer (options ignored): refused 64 by the session probe, nothing created',
    async () => {
      const f = await fixture(PLAIN, 'b2', false);
      const hp = need('FBC_BOUNCER2_HOSTPORT');
      const run = await runChild({
        PG_ADMIN_URL: urlFor(PLAIN, f.admin, f.adminPassword, f.db, 'sslmode=disable', hp),
        PG_DATABASE_URL: urlFor(PLAIN, 'crewflow_owner', f.ownerPassword, f.db, 'sslmode=disable', hp),
      });
      expect(run.code === 64, `B2: exit ${run.code} (${run.result?.code ?? ''})`);
      expect(run.out.includes(OWNER_BOOTSTRAP_MESSAGES.adminNotSessionStable), 'B2: the not-session-stable refusal is missing');
      expect(!(await ownerState(PLAIN)).exists, 'B2: crewflow_owner was created');
      assertClean(run);
    },
  ],
  [
    'B3 PG_ADMIN_URL through PgBouncer + PG_ADMIN_DIRECT_URL: created over the direct address',
    async () => {
      const f = await fixture(PLAIN, 'b3', false);
      const hp = need('FBC_BOUNCER2_HOSTPORT');
      const run = await runChild({
        PG_ADMIN_URL: urlFor(PLAIN, f.admin, f.adminPassword, f.db, 'sslmode=disable', hp),
        PG_ADMIN_DIRECT_URL: urlFor(PLAIN, f.admin, f.adminPassword, f.db),
        PG_DATABASE_URL: urlFor(PLAIN, 'crewflow_owner', f.ownerPassword, f.db),
        PG_SSL_CA_CERT_PATH: CA_PATH,
      });
      await created(PLAIN, f, run, 'B3');
      expect(run.out.includes(OWNER_BOOTSTRAP_MESSAGES.adminDirectUsed), 'B3: the PG_ADMIN_DIRECT_URL line is missing');
      assertClean(run);
    },
  ],
];

async function main(): Promise<number> {
  let failed = 0;
  const only = process.argv.slice(2);
  for (const [name, fn] of scenarios) {
    if (only.length && !only.some((o) => name.startsWith(o))) continue;
    try {
      await fn();
      log(`PASS | ${name}`);
    } catch (error) {
      failed += 1;
      const why = error instanceof Failed ? error.message : `unexpected ${(error as { code?: string }).code ?? (error as Error).name}`;
      log(`FAIL | ${name} | ${why}`);
    }
  }
  await reset(PLAIN).catch(() => undefined);
  await reset(SIM).catch(() => undefined);
  log(failed ? `${failed} FAILED` : 'ALL PASS');
  return failed ? 1 : 0;
}

main().then(
  (code) => process.exit(code),
  () => {
    log('FAILED: unexpected error (details not shown)');
    process.exit(70);
  },
);
